"""R3.34 - writes src/robustness/MODEL_DESCRIPTION.md from the actual code settings and the baseline run outputs."""
import json, platform, importlib.metadata as md
from pred_common import *
base = json.load(open(f'{OUT}/01_models_baseline.json'))
v = {p: md.version(p) for p in ['scikit-learn', 'xgboost', 'shap', 'numpy', 'pandas', 'scipy', 'geopandas', 'joblib', 'kneed']}
L = []
A = L.append
A('# Predictive models: full description (R3.34)\n')
A('Generated by `src/robustness/07_model_description.py` from the settings in `src/analysis/predict.ipynb` and the re-run in `src/robustness/01_baseline_models.py`.\n')
A('## Data and targets\n')
A(f'- Input: `dataset/clusters/clusters.shp` (12,344 favelas). `predict.ipynb` calls `dropna()` over all columns, leaving **{base["regime"]["n_train"] + base["regime"]["n_test"]:,}** favelas with complete data.')
A(f'- Candidate predictors: **{len(X_VARS)}** non-infrastructural variables (demographic, race/colour, deprivation index, land cover, risk area, slope, HAND, Sentinel-5P pollutants SO2/CO/O3/NO2, waste collection, establishments, intra-urban vegetation, distance to primary-care and inpatient hospitals):\n  `' + '`, `'.join(X_VARS) + '`.')
A('- Targets: `wtr_idx` (water index, regression), `sanit_idx` (sanitation index, regression), `cluster_3` (regime 0 Structured / 1 Partially Structured / 2 Unstructured, 3-class classification).')
A('- Preprocessing: `StandardScaler` fitted on the whole complete-case table, then split (the scaler is not refit on the training portion; irrelevant for tree models). No imputation, no log transform (the `np.log(population)` line is commented out).\n')
A('## Train/test split, cross-validation, metric, seed\n')
A('| Item | Setting |\n|---|---|')
A('| Hold-out split | `train_test_split(test_size=0.2, random_state=42)`; **stratified on the regime** for the classifier (water/sanitation regressors in this reconstruction use the same call without stratification; see note) |')
A(f'| Sizes | train {base["regime"]["n_train"]:,} / test {base["regime"]["n_test"]:,} |')
A('| Inner CV (feature selection) | `StratifiedKFold(5)` for classification, `KFold(5)` for regression (no shuffling; `RFECV(cv=5)`) |')
A('| Selection metric | accuracy (regime), R² (water, sanitation) |')
A('| Reported test metric | accuracy and macro-F1 (regime); R² (water, sanitation), on the 20% hold-out |')
A('| Seed | `random_state=42` in the split and in every Random Forest |\n')
A('## Models and hyper-parameters\n')
A('| Model | Estimator | Hyper-parameters | Search space / selection |\n|---|---|---|---|')
A('| Regime, main (RF+RFE) | `RandomForestClassifier` | `n_estimators=200, random_state=42`, all other arguments default (`max_depth=None, min_samples_split=2, min_samples_leaf=1, max_features="sqrt", bootstrap=True, criterion="gini"`) | **No hyper-parameter search.** Features chosen by `RFECV(step=1, cv=StratifiedKFold(5), scoring="accuracy")`, which removes the least important feature (impurity importance) one at a time and keeps the subset with the highest mean CV accuracy; the final RF is refit on the selected features |')
A('| Water index (RF+RFE) | `RandomForestRegressor` | `n_estimators=200, random_state=42`, other arguments default (`max_features=1.0, criterion="squared_error"`) | `RFECV(step=1, cv=KFold(5), scoring="r2")`; no hyper-parameter search |')
A('| Sanitation index (RF+RFE) | `RandomForestRegressor` | idem | idem |')
A('| Regime, Lasso (reported in `predict.ipynb`) | `LogisticRegressionCV` | `penalty="l1", solver="liblinear", scoring="accuracy", max_iter=1000, cv=StratifiedKFold(5)` | `Cs = np.logspace(-4, 4, 20)` (inverse regularisation strength grid) |')
A('| Regime, RF+SFS (reported in `predict.ipynb`) | `RandomForestClassifier(n_estimators=200, random_state=42)` | defaults otherwise | `SequentialFeatureSelector(direction="forward", scoring="accuracy", cv=StratifiedKFold(5), n_features_to_select="auto")` |')
A('| SHAP | `shap.TreeExplainer` on the fitted RF, computed on the test set | exact TreeSHAP, default `feature_perturbation` | mean(|SHAP|) over test favelas (summed over classes for the regime model) |\n')
A('Note: in the repository, `src/analysis/predict.ipynb` contains only the regime classifiers (Lasso, RF+RFECV, RF+SFS). The water and sanitation regressors behind the reported R² are not in the notebook; `src/robustness/01_baseline_models.py` reconstructs them with the same recipe (RF 200 trees, RFECV, R²), and the numbers below come from that re-run.\n')
A('## Results of the re-run (test set, 20% hold-out)\n')
A('| Target | n features selected / candidate | Test metric |\n|---|---|---|')
for k, name in [('water', 'Water index'), ('sanitation', 'Sanitation index'), ('regime', 'Regime')]:
    t = base[k]['test']; A(f'| {name} | {base[k]["n_selected"]} / {base[k]["n_features_all"]} | ' + ', '.join(f'{a} = {b:.4f}' for a, b in t.items()) + ' |')
A('\n## Final predictors selected by RFE (RFECV)\n')
for k, name in [('water', 'Water index'), ('sanitation', 'Sanitation index'), ('regime', 'Regime')]:
    imp = base[k]['importances']
    A(f'**{name}** ({base[k]["n_selected"]}): ' + ', '.join(f'`{f}` ({100*i:.1f}%)' for f, i in sorted(imp.items(), key=lambda x: -x[1])) + '\n')
A('(percentages are the Random-Forest impurity importances of the final refit model).\n')
A('## Software\n')
A(f'- Python {platform.python_version()} (README: 3.13.12); ' + ', '.join(f'{p} {x}' for p, x in v.items()) + ' (pinned in `requirements.txt`).')
A('- Run on CPU; `RFECV(n_jobs=-1)` parallelises over CV folds. Results are deterministic for a fixed seed on a given library version.')
open(os.path.join(os.path.dirname(__file__), 'MODEL_DESCRIPTION.md'), 'w').write('\n'.join(L) + '\n')
print('\n'.join(L))
